"""Fused single-launch CUDA top-k for RTX PRO 6000 (SM120).

One kernel, one launch (a 3-kernel version measured launch-bound here).
The whole structure is k-way merges of sorted lists, done with warp
shuffles (barrier-free) wherever possible:

  - grid = batch * S blocks; block b owns a contiguous segment of a row.
    Each thread scans its strided slice coalesced and keeps a
    descending-sorted local top-k in registers (insertion; amortized cheap
    for random data).
  - Per-warp merge: k rounds of shuffle argmax over the lanes' current
    heads; the winning lane advances its head. Each warp ends with its
    sorted top-k in shared memory.
  - Warp 0 merges the NW per-warp lists the same heads way (shuffle-only)
    and the winners write the block's sorted top-k to a staging buffer.
  - After that, __threadfence() + atomicAdd on a per-row counter. The last
    block of a row (old count == S-1) merges the row's S staged sorted
    segment lists (two-level: 8 warps x up to 32 lists, then an 8-way
    final) and writes the final values/indices, then resets the counter.
    Counters are zero-initialized once and self-reset every call.

Correctness note: a "position merge" (round r taking every list's r-th
entry) is NOT a valid merge of sorted lists; only winner-advance heads
merges are used.

The selection is implemented entirely in the CUDA kernel; none of
PyTorch's reduction / sorting ops (or their Tensor/aten variants) are
called. Scratch staging buffers are cached per shape (scratch, not
outputs; outputs are fresh tensors allocated every call).
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

OP_TYPE = "topk"
SUPPORTED_PRECISIONS = ["fp32"]
HARDWARE_REQUIRED = ["RTX_PRO_6000", "H100", "B200"]

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>
#include <ATen/cuda/CUDAContext.h>

// Full-warp argmax over (val, idx) pairs with deterministic tie-break
// (lowest lane wins). All lanes leave with the winner.
__device__ __forceinline__ void warp_argmax(float& val, int& idx) {
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        float ov = __shfl_down_sync(0xffffffffu, val, off);
        int   oi = __shfl_down_sync(0xffffffffu, idx, off);
        if (ov > val) { val = ov; idx = oi; }
    }
    val = __shfl_sync(0xffffffffu, val, 0);
    idx = __shfl_sync(0xffffffffu, idx, 0);
}

template <int KMAX>
__global__ void topk_fused_kernel(const float* __restrict__ x,
                                  float* __restrict__ gval,
                                  int* __restrict__ gidx,
                                  float* __restrict__ ovals,
                                  int64_t* __restrict__ oidx,
                                  int* __restrict__ counter,
                                  int n, int k, int S, int seglen, int nth) {
    int row = blockIdx.x / S;
    int seg = blockIdx.x - row * S;
    const float* xrow = x + (long long)row * (long long)n;
    long long base = (long long)seg * seglen;
    long long end = base + seglen;
    if (end > n) end = n;

    const int tid = threadIdx.x;
    const int warp = tid >> 5, lane = tid & 31;
    const int NW = nth >> 5;              // warps per block (8 for nth=256)
    __shared__ float wl[8][64];           // per-warp sorted lists
    __shared__ int   widx[8][64];
    __shared__ int   s_old;

    // ---- per-thread sorted local top-k ----
    float v[KMAX];
    int   id[KMAX];
    #pragma unroll
    for (int i = 0; i < KMAX; ++i) { v[i] = -INFINITY; id[i] = 0; }
    int cnt = 0;
    for (long long i = base + tid; i < end; i += nth) {
        float xv = xrow[i];
        if (cnt < k) {
            int p = cnt;
            while (p > 0 && v[p-1] < xv) { v[p] = v[p-1]; id[p] = id[p-1]; --p; }
            v[p] = xv; id[p] = (int)i; ++cnt;
        } else if (xv > v[k-1]) {
            int p = k - 1;
            while (p > 0 && v[p-1] < xv) { v[p] = v[p-1]; id[p] = id[p-1]; --p; }
            v[p] = xv; id[p] = (int)i;
        }
    }

    // ---- per-warp heads merge of the 32 sorted register lists ----
    // head = (v[p], id[p]); the winning lane advances its private head.
    {
        int p = 0;
        float hv = v[0];
        int   hi = id[0];
        for (int r = 0; r < k; ++r) {
            float val = hv; int idx = lane;   // payload: lane id
            warp_argmax(val, idx);
            int w = idx;                      // winning lane, all lanes
            if (lane == w) {
                wl[warp][r] = val;
                widx[warp][r] = hi;
                ++p;
                hv = (p < k) ? v[p] : -INFINITY;
                hi = (p < k) ? id[p] : 0;
            }
        }
    }
    __syncthreads();

    // ---- warp 0 merges the NW warp lists -> block's sorted top-k ----
    long long out = (long long)blockIdx.x * k;
    if (warp == 0) {
        int   p  = (lane < NW) ? 0 : 0;
        float hv = (lane < NW) ? wl[lane][0] : -INFINITY;
        for (int r = 0; r < k; ++r) {
            float val = hv; int idx = lane;
            warp_argmax(val, idx);
            int w = idx;
            if (lane == w) {
                gval[out + r] = val;
                gidx[out + r] = widx[w][p];
                ++p;
                hv = (p < k && lane < NW) ? wl[w][p] : -INFINITY;
            }
        }
    }

    // ---- last block of this row merges the S staged sorted lists ----
    __threadfence();
    __syncthreads();
    if (tid == 0) s_old = atomicAdd(counter + row, 1);  // old count
    __syncthreads();
    if (s_old != S - 1) return;   // only the last block of the row proceeds
    __threadfence();  // acquire: other blocks' candidate writes are visible

    long long gbase = (long long)row * S * k;
    float* fv = ovals + (long long)row * k;
    int64_t* fi = oidx + (long long)row * k;

    // level 1: each warp merges up to 32 segment lists of the row
    // (W32 = ceil(S/8) lists per warp, up to 32)
    const int W32 = (S + NW - 1) / NW;
    __shared__ float fl[8][64];
    __shared__ int   fli[8][64];
    if (warp < NW && lane == 0) {   // default: no list (all -inf)
        for (int r = 0; r < k; ++r) { fl[warp][r] = -INFINITY; fli[warp][r] = 0; }
    }
    if (warp < NW) {
        int l0 = warp * W32;
        int l1 = min(l0 + W32, S);
        int which = l0 + lane;
        int p = 0;
        float hv = (which < l1) ? __ldcg(gval + gbase + (long long)which * k)
                                : -INFINITY;
        for (int r = 0; r < k; ++r) {
            float val = hv; int idx = lane;
            warp_argmax(val, idx);
            int w = idx;
            if (lane == w && which < l1) {
                fl[warp][r] = val;
                fli[warp][r] = (int)__ldcg(gidx + gbase + (long long)which * k + p);
                ++p;
                hv = (which < l1 && p < k)
                     ? __ldcg(gval + gbase + (long long)which * k + p) : -INFINITY;
            }
        }
    }
    __syncthreads();

    // level 2: warp 0 merges the NW level-1 lists -> final output
    if (warp == 0) {
        int p = 0;
        float hv = (lane < NW) ? fl[lane][0] : -INFINITY;
        for (int r = 0; r < k; ++r) {
            float val = hv; int idx = lane;
            warp_argmax(val, idx);
            int w = idx;
            if (lane == w) {
                fv[r] = val;
                fi[r] = (int64_t)fli[w][p];
                ++p;
                hv = (p < k && lane < NW) ? fl[w][p] : -INFINITY;
            }
        }
    }
    if (tid == 0) *(counter + row) = 0;   // reset for the next call
}

void topk_cuda(torch::Tensor x, int64_t k_, int64_t S_,
               torch::Tensor gval, torch::Tensor gidx, torch::Tensor counter,
               torch::Tensor outv, torch::Tensor outi) {
    TORCH_CHECK(x.dtype() == torch::kFloat32 && x.dim() == 2);
    auto xc = x.contiguous();
    int batch = (int)xc.size(0);
    int n = (int)xc.size(1);
    int k = (int)k_;
    int S = (int)S_;
    if (k <= 0 || n == 0 || batch == 0) return;
    TORCH_CHECK(k <= 64, "k > 64 unsupported");

    const int nth = 256;

    long long seglen = ((long long)n + S - 1) / S;
    auto stream = at::cuda::getCurrentCUDAStream();
    int km = 1;                    // register list capacity: pow2 >= k
    while (km < k) km *= 2;
    #define LAUNCH(KM) topk_fused_kernel<KM><<<batch * S, nth, 0, stream>>>( \
        xc.data_ptr<float>(), gval.data_ptr<float>(), gidx.data_ptr<int>(), \
        outv.data_ptr<float>(), outi.data_ptr<int64_t>(), \
        counter.data_ptr<int>(), n, k, S, (int)seglen, nth)
    switch (km) {
        case 1:  LAUNCH(1);  break;
        case 2:  LAUNCH(2);  break;
        case 4:  LAUNCH(4);  break;
        case 8:  LAUNCH(8);  break;
        case 16: LAUNCH(16); break;
        case 32: LAUNCH(32); break;
        case 64: LAUNCH(64); break;
        default: TORCH_CHECK(false, "k > 64 unsupported"); break;
    }
    #undef LAUNCH
}
"""

_CPP_SRC = r"""
#include <torch/extension.h>
void topk_cuda(torch::Tensor x, int64_t k, int64_t S,
               torch::Tensor gval, torch::Tensor gidx, torch::Tensor counter,
               torch::Tensor outv, torch::Tensor outi);
"""

_ext = load_inline(
    name="topk_fused_v3",
    cpp_sources=_CPP_SRC,
    cuda_sources=_CUDA_SRC,
    functions=["topk_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


def _choose_s(batch: int, n: int, k: int) -> int:
    # constraints: S <= 256 (final merge = 8 warps x 32 lists);
    # seglen >= k so every segment yields k real candidates; ~1024 blocks
    s_target = max(1, 1024 // batch)
    return max(1, min(256, s_target, n // k))


_scratch_cache = {}


def _get_scratch(batch, k, device, S):
    key = (batch, k, device, S)
    ent = _scratch_cache.get(key)
    if ent is None:
        ent = (
            torch.empty(batch * S * k, dtype=torch.float32, device=device),
            torch.empty(batch * S * k, dtype=torch.int32, device=device),
            torch.zeros(batch, dtype=torch.int32, device=device),
        )
        _scratch_cache[key] = ent
    return ent


class Model(nn.Module):
    """Top-k over the last dim of a 2D fp32 tensor (custom CUDA kernel)."""

    def __init__(self, batch: int, n: int, k: int):
        super().__init__()
        self.batch, self.n, self.k = batch, n, k
        self.register_buffer("_dummy", torch.zeros(1))

    def forward(self, x: torch.Tensor):
        batch, n = x.shape
        k = self.k
        S = _choose_s(batch, n, k)
        gval, gidx, counter = _get_scratch(batch, k, x.device, S)
        # counters self-reset inside the kernel at the end of every call
        outv = torch.empty(batch, k, dtype=torch.float32, device=x.device)
        outi = torch.empty(batch, k, dtype=torch.int64, device=x.device)
        _ext.topk_cuda(x, k, S, gval, gidx, counter, outv, outi)
        return outv, outi


# Module-level shims rebuilt by check.py / benchmark.py per shape.
batch = 64
n = 8192
k = 8


def get_inputs():
    x = torch.randn(batch, n, dtype=torch.float32)
    return [x]


def get_init_inputs():
    return [batch, n, k]
